#include <stdio.h>

int main() {
    int logical[5] = {100, 200, 300, 400, 500};  /* 程序内的逻辑地址 */
    int base1 = 1000, base2 = 5000;              /* 不同装载基址 */

    printf("程序在基址 %d 处装入：\n", base1);
    for (int i = 0; i < 5; i++)
        printf("  逻辑%4d -> 物理 %d\n", logical[i], base1 + logical[i]);

    printf("程序在基址 %d 处装入（重定位）：\n", base2);
    for (int i = 0; i < 5; i++)
        printf("  逻辑%4d -> 物理 %d\n", logical[i], base2 + logical[i]);
    return 0;
}
